/** Device key kept in IndexedDB. It never leaves the browser. */
export interface StoredDevice {
  readonly deviceId: string;
  readonly key: CryptoKey;
}

/**
 * Persistence for the non-extractable device key.
 *
 * Preconditions: `save` is called with a key generated by `generateDeviceKey`.
 * Postconditions: `load` returns that key on this browser, or `null` on another one.
 */
export interface DeviceStore {
  /** Reads the device key, or `null` when this browser has none. */
  load(): Promise<StoredDevice | null>;
  /**
   * Replaces the device key.
   *
   * @param device - Device id and key.
   */
  save(device: StoredDevice): Promise<void>;
}

const DB_NAME = 'domusafe-device';
const STORE = 'key';

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore(STORE);
    };
    request.onsuccess = () => {
      resolve(request.result);
    };
    request.onerror = () => {
      reject(request.error ?? new Error('device database failed'));
    };
  });
}

/**
 * Device store backed by IndexedDB.
 *
 * @returns The store used by the vault screen.
 */
export function browserDeviceStore(): DeviceStore {
  return {
    async load() {
      const db = await openDb();
      try {
        return await new Promise((resolve, reject) => {
          const request = db.transaction(STORE, 'readonly').objectStore(STORE).get('current');
          request.onsuccess = () => {
            resolve((request.result as StoredDevice | undefined) ?? null);
          };
          request.onerror = () => {
            reject(request.error ?? new Error('device read failed'));
          };
        });
      } finally {
        db.close();
      }
    },
    async save(device) {
      const db = await openDb();
      try {
        await new Promise<void>((resolve, reject) => {
          const transaction = db.transaction(STORE, 'readwrite');
          transaction.objectStore(STORE).put(device, 'current');
          transaction.oncomplete = () => {
            resolve();
          };
          transaction.onerror = () => {
            reject(transaction.error ?? new Error('device write failed'));
          };
        });
      } finally {
        db.close();
      }
    },
  };
}

/**
 * Platform sent with a new device. Unknown browsers use `other`.
 *
 * @returns A platform accepted by the API.
 */
export function devicePlatform(): 'android' | 'ios' | 'windows' | 'macos' | 'linux' | 'other' {
  const agent = navigator.userAgent;
  if (/android/iu.test(agent)) {
    return 'android';
  }
  if (/iphone|ipad|ipod/iu.test(agent)) {
    return 'ios';
  }
  if (/windows/iu.test(agent)) {
    return 'windows';
  }
  if (/mac os/iu.test(agent)) {
    return 'macos';
  }
  if (/linux/iu.test(agent)) {
    return 'linux';
  }
  return 'other';
}
